using CardGame.Core;
using CardGame.Content.Standard;
internal static class SuFeiChecks
{
 private const string Owner="fixture:su-fei-owner",Driver="fixture:su-fei-driver",Quiet="fixture:su-fei-quiet",Watch="fixture:su-fei-watch",Mode="identity:classic-su-fei";
 public static void ConsecutiveNativeTargetsExactDrawGiftColdAndTurnQuota()
 {
  var(g,r)=Start();Play(g);UseNext(g,1);NoOffer(g);UseNext(g,2);NoOffer(g);UseNext(g,2);Offer(g);g=Cold(g,r);Activate(g);Gift(g);var first=E<LianpianDrawPaidEvent>(g).Single();var firstId=DrawnId(g,first);Need(first.ActualCount==1&&g.CardMovements.Count(m=>m.CardId==firstId&&m.From==CardLocation.DrawPile&&m.To==CardLocation.Hand(0)&&m.Sequence>first.Before&&m.Sequence<=first.After&&m.Reason.Value=="skill-program.lianpian.draw")==1,"The consecutive actual use pays exactly one genuine draw entity.");Need(Enumerable.Range(1,3).All(s=>g.CreateSnapshot(s).PendingDecision is null),"Foreign viewers cannot inspect the private exact drawn-card gift choice.");g=Cold(g,r);Answer(g,c=>c.Targets.SequenceEqual([2])&&c.Cards.SequenceEqual([firstId]));Play(g);Need(V(g,2).Hand.Any(c=>c.Id==firstId)&&E<LianpianGiftPaidEvent>(g).Single().TargetSeat==2,"Only the actual drawn physical entity reaches the common target.");
  for(var i=0;i<2;i++){UseNext(g,2);Offer(g);Activate(g);Gift(g);Answer(g,c=>c.Parameters.GetValueOrDefault("branch")=="keep");Play(g);}UseNext(g,2);NoOffer(g);Need(E<LianpianDrawPaidEvent>(g).Count()==3,"Three actual activations exhaust this real turn, independently of how many later matching uses occur.");var turn=g.CreateSnapshot(0).TurnNumber;End(g);Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard}&&g.CreateSnapshot(0).TurnNumber>turn);UseNext(g,2);NoOffer(g);UseNext(g,2);Offer(g);Activate(g);Gift(g);Answer(g,c=>c.Parameters.GetValueOrDefault("branch")=="keep");Play(g);Need(E<LianpianDrawPaidEvent>(g).Count()==4,"A new real Play resets its sequence and a new actual turn restores the three-use quota.");_=Cold(g,r);
 }
 public static void NativeBorrowedSwordUsesOnlyOrderedPrimaryTargets()
 {
  var(g,r)=Start(kind:CardKind.BorrowedSword);Play(g);Use(g,"equip",[1]);Play(g);Use(g,"equip",[2]);Play(g);Need(V(g,1).Equipment.Count>0&&V(g,2).Equipment.Count>0,"Two actual native equipment uses establish legal BorrowedSword pairs.");
  void Pair(int a,int b){var action=g.GetHumanLegalActions().First(x=>x.Kind==LegalActionKind.BorrowedSword&&x.TargetSeats.SequenceEqual([a,b]));NativeUse(g,action.CardId!.Value,[a,b]);}
  Pair(1,2);NoOffer(g);Pair(2,1);NoOffer(g);Need(E<SuFeiActualUseRecordedEvent>(g).TakeLast(2).Select(e=>e.Use.PrimaryTargets.Single()).SequenceEqual([1,2]),"Swapping weapon owner and requested victim does not make the auxiliary victim a shared independently designated target.");Pair(2,1);Offer(g);g=Cold(g,r);Activate(g);Gift(g);Need(P(g)!.Choices.Where(c=>c.Parameters.GetValueOrDefault("branch")=="give").All(c=>c.Targets.SequenceEqual([2])),"Only the repeated actual primary target may receive this exact draw, preserving each native pair order.");Answer(g,c=>c.Targets.SequenceEqual([2]));Play(g);Need(E<LianpianGiftPaidEvent>(g).Single().TargetSeat==2,"The real paired use completes with the primary recipient and genuine requested Slash children.");_=Cold(g,r);
  var(extra,er)=Start(kind:CardKind.BorrowedSword,redPairs:true);Reach(extra,()=>Optional(extra,"classic:fumian"));Activate(extra);Reach(extra,()=>P(extra)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("option-id")=="targets")==true);Answer(extra,c=>c.Parameters.GetValueOrDefault("option-id")=="targets");Play(extra);Use(extra,"equip",[1]);Play(extra);Use(extra,"equip",[2]);Play(extra);
  var prior=extra.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.BorrowedSword&&a.ConversionSource is not null&&a.ProgramActivationId is null&&a.TargetSeats.SequenceEqual([2,1]));Accept(extra,new PlayCardCommand(0,prior.CardId!.Value,prior.TargetSeats,extra.Revision,P(extra)!.PromptId,prior.PlayedCardKind,prior.TargetCardId){ConversionSource=prior.ConversionSource});NoOffer(extra);
  var added=extra.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.BorrowedSword&&a.ConversionSource is not null&&a.ProgramActivationId=="red-additional-targets"&&a.TargetSeats.SequenceEqual([1,2,2,1]));Accept(extra,new PlayCardCommand(0,added.CardId!.Value,added.TargetSeats,extra.Revision,P(extra)!.PromptId,added.PlayedCardKind,added.TargetCardId){ConversionSource=added.ConversionSource});Offer(extra);var actual=extra.ResolutionStack.OfType<CardUseFrame>().Single(f=>f.Action?.ActionId==extra.ResolutionStack.OfType<ProgramCardTriggerWindowFrame>().Last().Action.ActionId);Need(actual.Action!.TargetSeats.SequenceEqual([1,2,2,1])&&actual.Action.DesignatedTargetSeats!.SequenceEqual([1,2])&&actual.SuFeiQualification!.Current.PrimaryTargets.SequenceEqual([1,2])&&actual.SuFeiQualification.CommonTargets.SequenceEqual([2]),"A real red-additional converted four-seat action already stores compressed designated holders; Lianpian reads full native pairs once and retains the second primary.");extra=Cold(extra,er);Activate(extra);Gift(extra);Need(P(extra)!.Choices.Where(c=>c.Parameters.GetValueOrDefault("branch")=="give").All(c=>c.Targets.SequenceEqual([2])),"The genuine four-seat use offers only its common second primary, preserving both holder/victim pairs.");Answer(extra,c=>c.Targets.SequenceEqual([2]));Play(extra);Need(E<LianpianGiftPaidEvent>(extra).Single().TargetSeat==2,"The actual converted multi-pair native use completes its precise second-primary gift once.");_=Cold(extra,er);
 }
 private static int DrawnId(GameEngine g,LianpianDrawPaidEvent paid)=>g.CardMovements.Single(m=>m.Sequence>paid.Before&&m.Sequence<=paid.After&&m.From==CardLocation.DrawPile&&m.To==CardLocation.Hand(paid.Source.OwnerSeat)&&m.Reason.Value=="skill-program.lianpian.draw").CardId;
 private static void UseNext(GameEngine g,int target)=>NativeUse(g,V(g,0).Hand.First(c=>c.Kind==CardKind.Duel).Id,[target]);
 private static void Offer(GameEngine g){Reach(g,()=>Optional(g,"ol:lianpian")||P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});Need(Optional(g,"ol:lianpian"),"Expected actual consecutive native-use offer before Play returned.");}
 private static void NoOffer(GameEngine g){Reach(g,()=>Optional(g,"ol:lianpian")||P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});Need(!Optional(g,"ol:lianpian"),"An unmatched or exhausted native sequence must not offer Lianpian.");}
 private static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
 private static void Gift(GameEngine g)=>Reach(g,()=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="lianpian")==true);
 private static bool Optional(GameEngine g,string id)=>P(g)?.SkillPrompt?.SkillId==id&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];private static PendingDecision?P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p!=null);
    private static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}private static void Accept(GameEngine g,GameCommand c){var x=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(x.Accepted,x.Error?.Message??"Rejected SuFei command.");}private static void Answer(GameEngine g,Func<PromptChoice,bool>test){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(test).Id,g.Revision));}
    private static void Use(GameEngine g,string id,IReadOnlyList<int>targets)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,[],targets,g.Revision,P(g)!.PromptId));private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void NativeUse(GameEngine g,int id,IReadOnlyList<int>targets){var a=g.GetHumanLegalActions().First(a=>a.CardId==id&&(targets.Count==0||a.TargetSeats.SequenceEqual(targets)));Accept(g,new PlayCardCommand(0,id,a.TargetSeats,g.Revision,P(g)!.PromptId,a.PlayedCardKind,a.TargetCardId));}
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static void Reach(GameEngine g,Func<bool>done){for(var i=0;i<200;i++){if(done())return;var p=P(g);if(p?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip")==true)Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{Kind:DecisionKind.RescueDying,PlayerSeat:0})Answer(g,c=>c.Parameters.GetValueOrDefault("response")=="let-die");else if(p?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="lianpian")==true)Answer(g,c=>c.Parameters.GetValueOrDefault("branch")=="keep");else if(p is{PlayerSeat:0,Kind:DecisionKind.PlayCard})End(g);else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Small native SuFei fixture exceeded its boundary.");}
    private static string State(GameEngine g)=>System.Text.Json.JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>System.Text.Json.JsonSerializer.Serialize(f,f.GetType())),Commands=CommandJson.Serialize(g.AcceptedCommands)});private static GameEngine Cold(GameEngine g,ContentRegistry r){var restored=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(restored),"Every private viewer, exact acquired lease/debt and once-paid native child survives cold replay.");return restored;}
 private static (GameEngine,ContentRegistry)Start(CardKind kind=CardKind.Duel,bool watch=false,bool death=false,bool killTarget=false,bool redPairs=false)
 {
  var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(kind,watch,death,killTarget,redPairs));var g=GameEngine.CreateStandard(new GameOptions{Seed=7,PlayerCount=4,HumanSeat=0,HumanRole=watch?Role.Rebel:Role.Lord,ModeId=Mode,UseInteractiveSetup=true,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=16},r);Accept(g,new StartGameCommand());Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.SelectGeneral});Accept(g,new SelectGeneralCommand(0,Owner,g.Revision,P(g)!.PromptId));return(g,r);
 }
 private sealed class Fixture(CardKind kind,bool watch,bool death,bool killTarget,bool redPairs):IGameContentPackage
 {
  public PackageManifest Manifest{get;}=new("su-fei-fixture",new(1,0,0),[]);
