   Add(SkillProgramCatalog.Load(fixtureRules.ToJsonString(),"""{"schemaVersion":3,"skills":{"fixture:su-fei-driver":{"name":"真实补牌","description":"实际摸牌"},"fixture:su-fei-quiet":{"name":"静默","description":"跳其他出牌"}}}"""));
   if(watch){var rules="""{"schemaVersion":62,"skills":[{"id":"fixture:su-fei-watch","revision":1,"triggers":[{"id":"paid","window":"cardsGained","subject":"owner","destinationZones":["hand"],"movementReasons":["skill-program.lianpian.draw"],"movementOccurrence":"perBatch","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"chooseOption","target":"owner","resultBind":"child","options":[{"id":"continue"}]},{"op":"loseHp","target":"owner","amount":20}]},{"id":"loss","window":"dyingEntering","subject":"owner","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"recover","target":"owner","amount":20},{"op":"loseOwnerSkillsAndGrant","target":"owner","skillIds":["ol:lianpian","fixture:su-fei-watch"],"sourceBind":"fixture:su-fei-driver"}]}]}]}""";if(death){var node=System.Text.Json.Nodes.JsonNode.Parse(rules)!;node["skills"]![0]!["triggers"]!.AsArray().RemoveAt(1);rules=node.ToJsonString();}Add(SkillProgramCatalog.Load(rules,"""{"schemaVersion":3,"skills":{"fixture:su-fei-watch":{"name":"付款子链","description":"原生濒死失源或死亡","optionLabels":{"continue":"继续"}}}}"""));}
   if(killTarget)Add(SkillProgramCatalog.Load("""{"schemaVersion":62,"skills":[{"id":"fixture:su-fei-target-death","revision":1,"triggers":[{"id":"actual-target-dies","window":"cardUseTargetsFinalized","ownerRelation":"target","priority":1000,"optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"chooseOption","target":"owner","resultBind":"child","options":[{"id":"continue"}]},{"op":"loseHp","target":"owner","amount":20}]}]},{"id":"fixture:su-fei-first-hit-grant","revision":1,"triggers":[{"id":"native-first-hit","window":"afterDamageApplied","subject":"owner","damageOccurrence":"perDamage","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"grantSkills","target":"owner","skillIds":["fixture:su-fei-target-death"]}]}]}]}""","""{"schemaVersion":3,"skills":{"fixture:su-fei-target-death":{"name":"目标原生死亡","description":"较高优先级实际失去体力","optionLabels":{"continue":"继续"}},"fixture:su-fei-first-hit-grant":{"name":"实际受伤授予","description":"第一次原生伤害后才获得观察技能"}}}"""));
